#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048   /* 0x800 in the original binary */

/* URL‑decode a string.
 * src – input string (may contain %XX and '+')
 * dst – buffer for decoded string; must be large enough
 * Returns length of decoded string (excluding NUL). Always NUL‑terminates.
 */
static size_t url_decode(const char *src, char *dst)
{
    size_t out = 0;
    while (*src) {
        if (*src == '+') {
            dst[out++] = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hi = src[1];
            char lo = src[2];
            int hi_val = (hi >= '0' && hi <= '9') ? hi - '0' :
                         (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10 :
                         hi - 'A' + 10;
            int lo_val = (lo >= '0' && lo <= '9') ? lo - '0' :
                         (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10 :
                         lo - 'A' + 10;
            dst[out++] = (char)((hi_val << 4) | lo_val);
            src += 3;
        } else {
            dst[out++] = *src++;
        }
    }
    dst[out] = '\0';
    return out;
}

int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_LINE];
    static char val[MAX_LINE];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    size_t len = strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }

    char *pair = line;
    while (*pair) {
        char *amp = strchr(pair, '&');
        if (amp) *amp = '\0';

        char *eq = strchr(pair, '=');
        if (eq) {
            *eq = '\0';
            url_decode(pair, key);
            url_decode(eq + 1, val);
        } else {
            url_decode(pair, key);
            val[0] = '\0';
        }

        printf("%s=%s\n", key, val);

        if (!amp) break;
        pair = amp + 1;
    }
    return 0;
}
